package main

import "fmt"

type Handler func(string) string
type Middleware func(Handler) Handler

// chain 按注册顺序包裹：先注册的在外层，最先收到请求、最后返回响应。
func chain(h Handler, mws ...Middleware) Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

// withTrace 在最外层记录请求进出，用来观察包裹顺序。
func withTrace(next Handler) Handler {
	return func(req string) string {
		fmt.Println("[trace] 进入", req)
		defer fmt.Println("[trace] 离开")
		return next(req)
	}
}

// withAuth 先补上调用方身份，再把请求交给内层业务。
func withAuth(next Handler) Handler {
	return func(req string) string {
		return next("user=7 " + req)
	}
}

func main() {
	biz := func(req string) string { return "订单已创建:" + req }
	fmt.Println(chain(biz, withTrace, withAuth)("order=1001"))
}

