package main

import (
	"fmt"
	"strings"
)

// field 是结构化日志的一个键值对，机器解析比自由文本容易得多。
type field struct {
	key   string
	value string
}

// logLine 固定字段顺序拼装日志：stage 与 request_id 每个环节都要带上。
func logLine(stage, rid string, fields ...field) string {
	parts := []string{"stage=" + stage, "request_id=" + rid}
	for _, f := range fields {
		parts = append(parts, f.key+"="+f.value)
	}
	return strings.Join(parts, " ")
}

// handleOrder 模拟一次下单：requestID 从入口一路传到下游环节。
func handleOrder(rid string) {
	fmt.Println(logLine("gateway", rid, field{"path", "/orders"}))
	fmt.Println(logLine("order", rid, field{"action", "create"}))
	fmt.Println(logLine("stock", rid, field{"sku", "A-1"}))
}

func main() {
	// 入口只生成一次请求 ID，整条链路共用。
	handleOrder("req-9001")
}

