package main

import "fmt"

// bucket 模拟令牌桶：容量 burst，请求取走令牌，取不到就被限流。
type bucket struct {
	tokens int
	burst  int
}

// allow 先补令牌再取一个：refill 表示距上次请求新增的令牌数。
func (b *bucket) allow(refill int) bool {
	b.tokens += refill
	if b.tokens > b.burst {
		b.tokens = b.burst // 桶装满后多出来的令牌直接丢弃
	}
	if b.tokens == 0 {
		return false // 没有令牌就拒绝，保护后端
	}
	b.tokens--
	return true
}

func main() {
	b := &bucket{tokens: 3, burst: 3} // 桶初始是满的
	// 每个元素是本次请求到达前补充的令牌数（模拟时间流逝）。
	for i, refill := range []int{0, 0, 0, 1, 0} {
		if b.allow(refill) {
			fmt.Println("请求", i+1, "放行")
		} else {
			fmt.Println("请求", i+1, "限流")
		}
	}
}

