package main

import "fmt"

// 熔断器三态：闭合 正常调用 → 打开 快速失败 → 半开 试探能否恢复。
func main() {
	state, fails := "闭合", 0
	handle := func(ok bool) string {
		switch {
		case state == "打开":
			return "快速失败" // 故障未恢复前直接拒绝，别再拖垮依赖
		case state == "半开" && ok:
			state, fails = "闭合", 0
			return "试探成功 恢复闭合"
		case state == "半开":
			state = "打开"
			return "试探失败 重新打开"
		case ok:
			fails = 0
			return "调用成功"
		default:
			fails++
			if fails >= 2 { // 连续失败 2 次触发熔断
				state = "打开"
				return "调用失败 熔断打开"
			}
			return "调用失败"
		}
	}
	for i, ok := range []bool{false, false, false, false, true} {
		if i == 4 { state = "半开" } // 模拟冷却结束，放行一个试探请求
		before := state               // 先记下到达时的状态，再让 handle 推进它
		fmt.Println("请求", i+1, before, handle(ok))
	}
}

