package main

import "fmt"

// invoke 模拟一次带超时的调用：耗时超过 limit 就超时，二者先到者胜。
func invoke(cost, limit int) (string, bool) {
	resp, timeout := make(chan string, 1), make(chan bool, 1)
	if cost <= limit {
		resp <- "用户资料"
	} else {
		timeout <- true
	}
	select {
	case data := <-resp:
		return data, true
	case <-timeout:
		return "", false // 超时后本次调用作废，不再无限等待
	}
}

// retry 按策略重试：每次调用都有超时上限，耗尽次数后降级。
func retry(costs []int, limit int) {
	for i, cost := range costs {
		if data, ok := invoke(cost, limit); ok {
			fmt.Printf("第%d次调用成功: %s\n", i+1, data)
			return
		}
		fmt.Printf("第%d次调用超时，退避后重试\n", i+1)
	}
	fmt.Println("重试耗尽，返回降级数据")
}

func main() {
	retry([]int{8, 3}, 5) // 第一次 8ms 超过 5ms 上限，第二次 3ms 在窗口内
}

